[751]={"Die überfallene Karawane",{"Bringt Morin Cloudstalker in der Nähe von Bloodhoof die Dokumente der Venture Company."}},
[752]={"Eine bescheidene Bitte",{"Häuptling Hawkwind möchte, dass Ihr seine Mutter beim Brunnen südöstlich vom Camp Narache sucht."}},
[753]={"Eine bescheidene Bitte",{"Holt eine Wasserkanne vom Wasserbrunnen.","","Bringt die Kanne Häuptling Hawkwind im Camp Narache, das nordwestlich des Wasserbrunnens liegt."}},
[754]={"Säuberung von Winterhoof",{"Benutzt das Säuberungstotem von Winterhoof beim Wasserbrunnen von Winterhoof und kehrt dann zu Mull Thunderhorn zurück."}},
[755]={"Riten der Erdenmutter",{"Begebt Euch zu Seher Graytongue, der in den Hügeln direkt südlich des Lagers Narache lebt."}},
[756]={"Thunderhorn-Totem",{"Bringt Mull Thunderhorn 6 Pirscherklauen und 6 Pumaklauen."}},
[757]={"Ritus der Kraft",{"Tötet die Borstennacken in der Dornrankenklamm und bringt Häuptling Hawkwind im Camp Narache 12 Gürtel der Borstennacken."}},
[758]={"Säuberung von Thunderhorn",{"Benutzt dasSäuberungstotem von Thunderhorn beim Wasserbrunnen von Thunderhorn und kehrt dann zu Mull zurück."}},
[759]={"Wildmane-Totem",{"Bringt Mull Thunderhorn in Bloodhoof 8 Präriealphazähne."}},
[760]={"Säuberung von Wildmane",{"Benutzt das Säuberungstotem von Wildmane beim Wasserbrunnen von Wildmane und kehrt dann zu Mull Thunderhorn zurück."}},
[761]={"Sturzfliegerjagd",{"Bringt Harken Windtotem in Bloodhoof 8 Trophäen-Sturzfliegerkiele."}},
[762]={"Ein Botschafter des Bösen",{"Tötet den Botschafter Infernus in der Festung Angor und bringt Berater Belgrum in Ironforge einen Beweis seines Tod."}},
[763]={"Riten der Erdenmutter",{"Bringt Baine Bloodhoof in Bloodhoof Hawkwinds Totem. Folgt der Straße, die aus dem Camp Narache herausführt."}},
[764]={"Die Venture Company",{"Tötet für Morin Cloudstalker in der Nähe von Bloodhoof 14 Tagelöhner der Venture Co. und 6 Vorsteher der Venture Co."}},
[765]={"Vorsteher Fizsprocket",{"Tötet Vorsteher Fizsprocket und bringt Morin Cloudstalker in der Nähe von Bloodhoof dessen Klemmbrett."}},
[766]={nil,{"Bringt Maur Raincaller in Bloodhoof ein Herz eines Präriewolfs, einen Knochen eines Flachlandpumas, eine Schuppe eines Ebenenschreiters und einen Muskelmagen eines Sturzfliegers."}},
[767]={"Ritus der Sicht",{"Sprecht in Bloodhoof mit Zarlman Two-Moons."}},
[768]={"Leder sammeln",{"Bringt Veren Tallstrider in Thunder Bluff 12 Stücke leichtes Leder."}},
[769]={"Kodobalgtasche",{"Bringt Veren Tallstrider in Thunder Bluff 4 Einheiten leichtes Leder und 4 grobe Fäden."}},
[770]={"Der Dämonennarbenumhang",{"Sucht jemanden, der etwas über Geistheuler weiß."}},
[771]={"Ritus der Sicht",{"Sammelt 2 Quellsteine und 2 Bernsteinkörner und bringt sie Zarlman Two-Moons in Bloodhoof."}},
[772]={"Ritus der Sicht",{"Trinkt vor dem Stammesfeuer in Bloodhoof das Wasser der Seher und folgt der Vision, sobald sie erscheint."}},
[773]={"Ritus der Weisheit",{"Reist von Thunder Bluff gen Osten zu den Teufelsfelsen und sprecht mit dem Vorfahrengeist."}},
[775]={"Reise nach Thunder Bluff",{"Sprecht in Thunder Bluff mit Cairne Bloodhoof."}},
[776]={"Riten der Erdenmutter",{"Cairne Bloodhoof in Thunder Bluff möchte, dass Ihr ihm das Horn von Arra'chea bringt."}},
[777]={"Das wird schwierig",{"Bringt Lotwil Veriatus ein Zahnrad Nr. 5."}},
[778]={"Das wird schwierig",{"Besiegt den Fam'retor-Wächter und bringt Lotwils Fesseln der Elementarbindung zu Lotwil Veriatus zurück."}},
[779]={"Siegel der Erde",nil},
[780]={"Die Kampfeber",{"Grull Hawkwind im Camp Narache möchte, dass Ihr für ihn Kampfeber tötet und ihm 8 Kampfeberschnauzen und 8 Kampfeberflanken bringt."}},
[781]={"Angriff auf Camp Narache",{"Bringt Häuptling Hawkwind im Camp Narache die Angriffspläne der Borstennacken."}},
[782]={"Zerbrochene Allianzen",{"Tötet Tho'grun und bringt Gorn in Kargath das Zeichen der Erde."}},
[783]={"Die Bedrohung von innen",{"Sprecht mit Marshal McBride."}},
[784]={"Vernichtet die Verräter",{"Tötet 10 Matrosen von Kul Tiras, 8 Marinesoldaten von Kul Tiras sowie Lieutenant Benedict und kehrt dann zu Gar'Thok in Klingenhügel zurück."}},
[786]={"Vereitelung der Kolkaraggression",{"Lar Prowltusk außerhalb von Sen'jin möchte, dass Ihr die 3 Sets der Angriffspläne zerstört, die innerhalb der Kolkarklippe verwahrt werden."}},
[788]={"Scharfe Zähne",{"Tötet 10 scheckige Eber und kehrt dann zu Gornek beim Höhlenbau zurück."}},
[789]={"Stich des Skorpiden",{"Bringt 10 Skorpidarbeiterschwänze zu Gornek im Höhlenbau."}},
[790]={nil,{"Tötet Sarkoth und bringt seine Klaue zu Hana'zua."}},
[791]={"Akzeptiert Euer Schicksal",{"Furl Scornbrow im Wachturm von Klingenhügel möchte 8 Segeltuchreste haben."}},
[792]={"Üble Familiare",{"Tötet 12 üble Familiare.","","Kehrt dann zu Zureetha Fargaze beim Höhlenbau zurück."}},
[793]={"Zerbrochene Allianzen",{"Benutzt das Zeichen der Erde, um die Säulen aus Diamant, Opal und Amethyst zu aktivieren und die Runensteine zu holen.","","Legt die Runensteine auf das Siegel der Erde, um Schattenbringer und Hematus zu befreien.","","Tötet sie und bringt dann Gorn Schattenbringers Bindung, Hematus' Ketten und das Zeichen der Erde."}},
[794]={"Medaillon der Burning Blade",{"Bringt Zureetha Fargaze beim Höhlenbau das Medaillon der Burning Blade."}},
[795]={"Siegel der Erde",nil},
[804]={nil,{"Informiert Gornek beim Höhlenbau über Hana'zuas Notlage."}},
[805]={"Bericht erstatten in Sen'jin",{"Sprecht mit Meister Gadrin in Sen'jin."}},
[806]={"Dunkle Stürme",{"Bringt Fizzles Klaue zu Orgnil Soulscar in Klingenhügel."}},
[808]={"Minshinas Schädel",{"Holt Minshinas Schädel aus dem Kreis der Macht auf den Echoinseln.","","Bringt ihn Meister Gadrin in Sen'jin."}},
[809]={nil,{"Sprecht im Brachland mit Ak'Zeloth."}},
[812]={"Heilmittel benötigt",{"Sucht Kor'ghan in Orgrimmar und besorgt das Siechstachelgegengift. Bringt das Gegengift dann zu Rhinag an der nordwestlichen Grenze von Durotar."}},
[813]={"Suche nach dem Gegengift",{"Bringt Kor'ghan in Orgrimmar 4 Giftbeutel eines Siechstachelskorpiden."}},
[815]={"Zerbrecht ein paar Eier",{"Bringt dem Koch Torka in Klingenhügel 3 Schwanzpeitscher-Eier."}},
[816]={"Verloren, aber nicht vergessen",{"Bringt Misha Tor'kren auf dem Bauernhof nordwestlich von Klingenhügel einen Hinweis auf Krons Schicksal."}},
[817]={"Praktische Beute",{"Bringt Vel'rin Fang in Sen'jin 4 Durotar-Tigerfelle."}},
[818]={"Ein geistvolles Getränk",{"Bringt Meister Vornal in Sen'jin 4 intakte Makruraaugen und 8 Phiolen Kriechersekret."}},
[819]={"Chens leeres Fässchen",{"Sucht jemanden, der etwas über Chens leeres Fässchen weiß."}},
[821]={"Chens leeres Fässchen",{"Bringt Braumeister Drohn in Ratchet 5 Savannenlöwenhauer, 5 Ebenenschreiternieren und 1 Donnerechsenhorn."}},
[822]={"Chens leeres Fässchen",{"Bringt Braumeister Drohn in Ratchet 5 Blitzschlagdrüsen, 1 Donnerfalkenspeicheldrüse und 1 Kodoleber."}},
[823]={"Bericht an Orgnil",{"Sprecht mit Orgnil Soulscar in Klingenhügel."}},
[824]={"Je'neu vom Irdenen Ring",{"Bringt die beschmutzte Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale."}},
[825]={"Aus den Wrackteilen geborgen...",{"Gar'Thok von Klingenhügel möchte, dass Ihr 3 Gnomen-Werkzeuge aus den Wrackteilen vor der Küste holt."}},
[826]={nil,{"Besiegt Zalazane.","","Tötet 8 Voodootrolle und 8 verhexte Trolle.","","Bringt Gadrin Zalazanes Kopf."}},
[827]={"Die Knochenhöhle",{"Besorgt von den Kultisten an der Knochenhöhle ein paar Senghalsbänder.","","Bringt sie Margoz in seinem Lager."}},
[828]={nil,{"Sprecht mit Margoz."}},
[829]={nil,{"Bringt Neeru Fireblade in Orgrimmar ein Senghalsband-Muster."}},
[830]={"Die Befehle des Admirals",{"Bringt Gar'Thok in Klingenhügel Admiral Proudmoores Befehle."}},
[831]={"Die Befehle des Admirals",{"Bringt Nazgrel in Thralls Kammer in Orgrimmar Admiral Proudmoores Befehle."}},
[832]={"Brennende Schatten",{"Bringt Neeru Fireblade dieses Auge."}},
[833]={"Eine heilige Bestattung",{"Der Hüter des Wissens Raintotem möchte, dass Ihr bei den Teufelsfelsen 8 Eindringlinge der Borstennacken tötet."}},
[834]={"Wind in der Wüste",{"Holt 5 Säcke Vorräte und bringt sie Rezlak in der Nähe von Orgrimmar."}},
[835]={"Sicherung der Linien",{"Tötet für Rezlak in der Nähe der Staubwindklamm 12 Wilde der Staubschwingen und 8 Sturmhexen der Staubschwingen."}},
[836]={"Rettet OOX-09/HL!",{"Eskortiert OOX-09/HL zur Küste jenseits der Aussichtsklippen und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay."}},
[837]={"Übergriff",{"Tötet für Gar'Thok in Klingenhügel 4 Stacheleber der Grimmhauer, 4 Späher der Grimmhauer, 4 Staubläufer der Grimmhauer und 4 Schlachtwachen der Grimmhauer."}},
[838]={nil,{"Sprecht mit Apotheker Dithers am Bollwerk, Westliche Pestländer."}},
[840]={"Freiwilliger der Horde",{"Folgt der westlichen Straße aus Klingenhügel ins Brachland und über die Brücke.","","Macht bei dem Außenposten der Orcs auf der anderen Seite Halt.","","Gebt Kargal Battlescar im Brachlandaußenposten Euren Anwerbungsbrief."}},
[841]={"Eine weitere Kraftquelle?",{"Bringt Chefingenieur Bilgewhizzle in Gadgetzan 10 Wasserbeutel eines Wüstenläufers im Austausch gegen eine weitere Kraftquelle."}},
[842]={"Crossroads-Wehrpflicht",{"Folgt der Straße von Kargals fernem Farwatch-Außenposten nach Westen.","","Wendet Euch bei der Einmündung nach links und folgt dann der Straße in südliche Richtung.","","Sucht Sergra Darkthorn an der Kreuzung zweier Straßen in Crossroads auf."}},
[843]={"Ganns Rekultivierung",{"Gann Stonespire möchte, dass Ihr 15 Ausgräber von Bael'dun und 5 Großknechte von Bael'dun tötet.","","Bringt Gann Stonespire dann Khazgorms Tagebuch."}},
[844]={"Ebenenschreiter-Bedrohung",{"Besorgt 7 Ebenenschreiterschnäbel und bringt sie Sergra Darkthorn in Crossroads."}},
[845]={"Die Zhevras",{"Erschlagt Zhevra-Läufer, um für Sergra Darkthorn in Crossroads 4 Zhevra-Hufe zu erhalten."}},
[846]={"Ganns Rache",{"Gann Stonespire möchte, dass Ihr ihm 6 Phiolen Nitroglyzerin, 6 Teile Holzbrei und 6 Proben Natriumnitrat bringt."}},
[847]={"Arglist des Raptors",{"Sprecht mit Tor'gan."}},
[848]={"Pilzsporen",{"Bringt dem Apotheker Helbrim in Crossroads 4 Pilzsporen."}},
[849]={"Ganns Rache",{"Zerstört den Flugapparat bei Beal Modan und kehrt dann zu Gann Stonespire zurück."}},
[850]={"Anführer der Kolkar",{"Bringt Regthar Deathgate westlich von Crossroads Baraks Kopf."}},
[851]={"Verog der Derwisch",{"Bringt Regthar Deathgate westlich von Crossroads Verogs Kopf."}},
[852]={"Hezrul Blutmal",{"Bringt Regthar Deathgate westlich von Crossroads Hezruls Kopf."}},
[853]={"Apothekerin Zamah",{"Bringt der Apothekerin Zamah in Thunder Bluff die weiterverarbeiteten Sporen, bevor die Zeit abgelaufen ist."}},
[854]={"Reise nach Crossroads",{"Sprecht mit Thork in Crossroads im Brachland."}},
[855]={"Zentaurenarmschienen",{"Bringt Regthar Deathgate westlich von Crossroads 15 Zentaurenarmschienen."}},
[857]={"Die Träne der Monde",{"Feegly der Verbannte möchte, dass Ihr ihm die Träne der Monde zurückbringt."}},
[858]={"Zündung",{"Holt den Zündschlüssel und bringt ihn Wizzlecrank."}},
[860]={nil,{"Sprecht in Crossroads mit Sergra Darkthorn."}},
[861]={"Der Weg der Jäger",{"Bringt Melor Stonehoof in Thunder Bluff 4 Flachlandstreunerklauen."}},
[862]={"Grubenratteneintopf",{"Bringt Grub östlich von Crossroads 8 Grubenratten."}},
[863]={"Die Flucht",{"Schützt Wizzlecrank und den gestohlenen Goblinschredder auf dem Weg zu Sputtervalve in Ratchet."}},
[864]={"Kehrt zu Apothekerin Zinge zurück",{"Bringt das versiegelte Feldtestset nach Undercity zu Apothekerin Zinge."}},
[865]={"Raptorhörner",{"Sammelt 5 intakte Raptorhörner von Bluthornsensenklauen und bringt sie Mebok Mizzyrix in Ratchet."}},
[866]={"Wurzelproben",{"Bringt Mebok Mizzyrix in Ratchet 8 Wurzelproben."}},
[867]={"Räuberische Harpyien",{"Sammelt 8 Krallen der Hexenschwingen.","","Bringt sie Darsok Swiftdagger in Crossroads."}},
[868]={"Eierjagd",{"Bringt Korran in Crossroads 12 Silithideneier und die Grabgabel."}},
[869]={"Raptorendiebe",{"Bringt Gazrog in Crossroads 12 Raptorenköpfe."}},
[870]={"Die vergessenen Teiche",{"Berichtet Tonga Runetotem von Euren Entdeckungen."}},
[871]={"Vereitelung der Angriffe",{"Tötet 8 Wassersucher, 8 Dornwirker sowie 3 Jäger des Grimmhauerstamms und kehrt dann zu Thork in Crossroads zurück."}},
[872]={"Das Ende der Unterbrechungen",{"Tötet 8 Geomanten der Grimmhauer, 8 Verteidiger der Grimmhauer und Kreenig Grantelschnauze.","","Bringt dann Thork in Crossroads Kreenig Grantelschnauzes Hauer."}},
[873]={nil,{"Bringt Mahren Skyseer das Herz von Isha Awak."}},
[874]={nil,{"Sprecht mit Mahren Skyseer."}},
[875]={"Offiziere der Harpyien",{"Sammelt 6 Harpyienoffiziersringe von den Tötern der Hexenschwingen und kehrt dann zu Darsok Swiftdagger in Crossroads zurück."}},
[876]={"Serena Blutfeder",{"Erschlagt Serena Blutfeder und bringt Darsok Swiftdagger in Crossroads ihren Kopf."}},
[877]={"Die brackige Oase",{"Kehrt zu Tonga in Crossroads zurück, nachdem Ihr die brackige Oase untersucht habt."}},
[878]={"Stämme im Krieg",{"Erledigt 6 Wassersucher der Borstennacken, 12 Dornenwirker der Borstennacken sowie 12 Geomanten der Borstennacken und kehrt zu Quetschzahn im Camp Taurajo im Brachland zurück."}},
[879]={"Verräter in den eigenen Reihen",{"Tötet Nak, Kuz und Lok Orcbane und bringt Quetschzahn im Camp Taurajo im Brachland ihre Schädel."}},
[880]={"Veränderte Wesen",{"Bringt Tonga Runetotem in Crossroads 8 veränderte Schnappkieferschalen."}},
[881]={nil,{"Bringt Sergra Darkthorn in Crossroads Echeyakees Balg."}},
[882]={nil,{"Bringt Jorn Skyseer im Camp Taurajo Ishamuhales Fangzahn."}},
[883]={nil,{"Bringt Jorn Skyseer im Camp Taurajo Lakota'manis Huf."}},
[884]={nil,{"Bringt Jorn Skyseer im Camp Taurajo Owatankas Schwanzstachel."}},
[885]={nil,{"Bringt Jorn Skyseer im Camp Taurajo Washte Pawnes Feder."}},
[886]={"Die Oasen des Brachlandes",{"Sprecht in Crossroads mit Tonga Runetotem."}},
[887]={"Südmeerfreibeuter",{"Tötet für Gazlowe in Ratchet 12 Briganten der Südmeerfreibeuter und 6 Kanoniere der Südmeerfreibeuter."}},
[888]={"Gestohlene Beute",{"Bringt Gazlowe in Ratchet die Stiefellieferung und die Teleskoplinse zurück."}},
[889]={"Geist des Windes",{"Bringt Tatternack Steelforge in Crossroads 20 Blutsplitter."}},
[890]={"Die verloren gegangene Lieferung",{"Bringt Werftmeister Dizzywig Gazlowes Geschäftsbuch."}},
[891]={"Die Kanonen von Northwatch",{"Kapitän Thalo'thas Brightsun aus Ratchet möchte, dass Ihr 10 Medaillen von Theramore sammelt und Captain Hellstieg, Kanonier Knoch und Kanonier Hecksler tötet."}},
[892]={"Die verloren gegangene Lieferung",{"Bringt Gazlowe in Ratchet sein Geschäftsbuch zurück."}},
[893]={"Ausgewählte Waffen",{"Bringt Tatternack Steelforge im Camp Taurajo im Brachland einen Grimmhauerrückenstecher, einen verkohlten Grimmhauerzauberstab und einen Grimmhauerkriegsschild."}},
[894]={"Samophlang",{"Verschafft Euch Zugang zur Steuerkonsole in der Forschungseinrichtung der Venture Company."}},
[895]={"GESUCHT: Baron Küstenschipper",{"Bringt Gazlowe in Ratchet Baron Küstenschippers Kopf."}},
[896]={"Des Minenarbeiters Vermögen",{"Beschafft Euch von einem der Vorarbeiter oder Vollstrecker der Venture Company den Katzenaugensmaragd und bringt ihn zu Dizzywig in Ratchet."}},
[897]={"Der Ernter",{"Bringt den Ernterkopf zu Jorn Skyseer."}},
[898]={"Aus der Gefangenschaft befreit",{"Begleitet Gilthares Firebough sicher zurück zu Kapitän Brightsun in Ratchet."}},
[899]={"Von Hass zerfressen",{"Bringt Mankrik in Crossroads 60 Stacheleberhauer der Borstennacken."}},
[900]={"Samophlang",{"Schließt das Treibstoffzufuhrventil, das Regelventil und das Hauptsteuerventil, und benutzt dann noch einmal die Steuerkonsole."}},
[901]={"Samophlang",{"Besorgt Euch bei Tüftler Sniggles den Konsolenschlüssel, um damit die Steuerkonsole zu öffnen."}},
[902]={"Samophlang",{"Bringt das Samophlang zu Sputtervalve in Ratchet."}},
[903]={"Streuner des Brachlandes",{"Besorgt für Sergra Darkthorn in Crossroads 7 Streunerklauen von den Savannenstreunern."}},
[905]={"Die wütenden Sensenklauen",{"Tötet Bluthornraptoren und nehmt ihre Federn mit. Benutzt die Federn bei den drei Sensenklauennestern. Kehrt zu Sergra Darkthorn in Crossroads zurück."}},
[906]={"Verräter in den eigenen Reihen",{"Bringt Loks Kopf zu Thork in Crossroads im Brachland."}},
[907]={"Wütende Donnerechsen",{"Bringt das Blut von 3 Donnerechsen ins Camp Taurajo zu Jorn Skyseer."}},
[913]={"Der Ruf des Donnerfalken",{"Sucht und erschlagt einen Donnerfalken und bringt Jorn Skyseer in Taurajo seine Flügel."}},
[914]={"Anführer der Giftzähne",{"Bringt die Edelsteine von Kobrahn, Anacondra, Pythas und Serpentis nach Thunder Bluff zu Nara Wildmane."}},
[916]={"Waldwebergift",{"Bringt Gilshalan Windwalker in Aldrassil 10 Waldwebergiftbeutel."}},
[917]={"Waldweberei",{"Bringt Gilshalan in Aldrassil ein Waldweberei."}},
[918]={"Bäumlingssamenkörner",{"Bringt Denalan am Al'Amethsee 8 Bäumlingssamenkörner."}},
[919]={"Bäumlingssprossen",{"Bringt Denalan am Al'Amethsee 12 Bäumlingssprossen."}},
[920]={"Tenarons Einladung",{"Sprecht in Shadowglen über den Dächern von Aldrassil mit Tenaron Stormgrip."}},
[921]={"Krone der Erde",{"Füllt die Kristallphiole und bringt sie Tenaron Stormgrip über den Dächern von Aldrassil."}},
[922]={nil,{"Bringt Rellian Greenspyre in Darnassus ein Bäumlingssamenkorn."}},
[923]={"Tumore",{"Bringt Rellian Greenspyre in Darnassus 5 moosartige Tumore."}},
[924]={"Die Dämonensaat",{"Nehmt einen fehlerhaften Kraftstein. Bringt ihn zum Altar des Feuers, bevor dessen Wirkung erlischt, und kehrt dann zu Ak'Zeloth zurück."}},
[926]={"Fehlerhafter Kraftstein",nil},
[927]={"Das moosumschlungene Herz",{"Bringt Denalan am Al'Amethsee das moosumschlungene Herz."}},
[928]={"Krone der Erde",{"Bringt Corithras Moonrage in Dolanaar das teilweise gefüllte Gefäß."}},
[929]={"Krone der Erde",{"Füllt die Jadephiole und bringt sie Corithras Moonrage in Dolanaar zurück."}},
[930]={"Die leuchtende Frucht",{"Bringt Denalan am Al'Amethsee die leuchtende Frucht."}},
[931]={"Der schimmernde Wedel",{"Bringt Denalan am Al'Amethsee einen der schimmernden Wedel."}},
[932]={"Krankhafter Hass",{"Tötet Lord Melenas und bringt Tallonkai Swiftroot in Dolanaar seinen Kopf."}},
[933]={"Krone der Erde",{"Füllt die Turmalinphiole und bringt sie Corithras Moonrage in Dolanaar."}},
[935]={"Krone der Erde",{"Bringt dem Erzdruiden Fandral Staghelm in Darnassus das gefüllte Gefäß."}},
[937]={"Die verzauberte Lichtung",{"Beschafft 6 Blutfedergürtel und bringt sie der Schildwache Arynia Cloudsbreak in der Lichtung des Orakels."}},
[938]={"Nebel",{"Begleitet Nebel zur Schildwache Arynia Cloudsbreak beim Mondbrunnen in der Nähe des Orakelbaums."}},
[939]={"Flöte des Xavaric",{"Bringt die Flöte von Xavaric und 5 Jadefeuerteufelsbinder zu Eridan Bluewind im südlichen Teil des Teufelswalds."}},
[940]={nil,{"Überbringt dem Erzdruiden Fandral Staghelm in Darnassus den Bericht des Orakelbaums."}},
[941]={"Das Einpflanzen des Herzens",{"Pflanzt das besudelte Herz in Denalans Blumentopf ein."}},
[942]={"Der geistesabwesende Ausgrabungsleiter",{"Bringt das rätselhafte Fossil zum Archäologen Flagongut im Hafen von Menethil."}},
[943]={"Der geistesabwesende Ausgrabungsleiter",{"Der Archäologe Flagongut im Hafen von Menethil möchte, dass Ihr ihm den Stein von Relu und Flagonguts Fossil bringt."}},
[944]={"Die Meistergleve",{"Tragt Informationen zusammen und benutzt dann die Wahrsagephiole, um eine Wahrsageschale zu erschaffen. Benutzt die Schale, um mit Onu zu sprechen."}},
[945]={"Therylunes Flucht",{"Verhelft Therylune zur Flucht und teilt dann Therysil beim Schrein von Aessina mit, dass ihre Schwester in Sicherheit ist."}},
[947]={"Höhlenpilze",{"Bringt Barithras Moonshade in Auberdine 5 Schorfstänglinge und 1 Todeskappe."}},
[948]={nil,{"Sprecht im Hain der Uralten mit Onu."}},
[949]={"Das Twilight-Lager",{"Sucht im Lager des Klans der Twilight-Hammer in der Meistergleve nach einem Hinweis."}},
[950]={"Rückkehr zu Onu",{"Bringt Onu das irrsinnige Gekritzel, das Ihr gefunden habt."}},
[951]={"Mathystra-Relikte",{"Bringt 6 Mathystra-Relikte zu Onu in den Hain der Uralten."}},
[952]={"Der Hain der Uralten",{"Bringt Fandrals Nachricht zu Onu in den Hain der Uralten in Dunkelküste, südlich von Auberdine."}},
[953]={"Der Untergang von Ameth'Aran",{"Studiert die Schrifttafeln, die von Ameth'Aran und ihrem Untergang erzählen, und kehrt dann zur Schildwache Tysha Moonblade in Dunkelküste zurück."}},
[954]={nil,{"Sucht in den Ruinen von Bashal'Aran nach der Quelle der seltsamen blauen Aura."}},
[955]={nil,{"Beschafft für Asterion in Bashal'Aran 8 Grell-Ohrringe."}},
[956]={nil,{"Beschafft das alte Mondstein-Siegel und bringt es Asterion in Bashal'Aran."}},
[957]={nil,{"Zerstört das alte Mondstein-Siegel in der uralten Flamme in Ameth'Aran und kehrt dann zu Asterion in Bashal'Aran zurück."}},
[958]={"Werkzeuge der Hochgeborenen",{"Sucht sieben Hochgeborenenrelikte und bringt sie Thundris Windwirker in Auberdine."}},
[959]={"Ärger auf den Docks",{"Kranführer Bigglefuzz in Ratchet möchte, dass Ihr Zausel dem Verrückten, der sich in den Höhlen des Wehklagens versteckt, die Flasche mit 99-jährigem Portwein wieder abnehmt."}},
