[4382]={"Kristallkraft",nil},
[4383]={"Kristallbarriere",nil},
[4384]={"Kristallschwächer",nil},
[4385]={"Kristallsprengladung",nil},
[4386]={"Kristallspitze",nil},
[4402]={"Galgars Kaktusapfel Surprise",{"Bringt Galgar 10 Kaktusäpfel. Ihr erinnert Euch, dass er gesagt hat, man fände sie in der Nähe von Kakteen."}},
[4421]={"Die Verderbnis der Jadefeuer",{"Tötet Xavathras sowie 11 Jadefeuerteufelsanbeter, 9 Jadefeuerschattenpirscher und 9 Jadefeuerschurken. Kehrt zu Eridan Bluewind im Teufelswald zurück, sobald die Aufgabe erledigt ist."}},
[4441]={"Gebundene Urtume",{"Begebt Euch nach Darnassus und verwendet Eridans Phiole, um Euch im Tempel des Mondes eine Phiole mit gesegnetem Wasser zu holen. Kehrt mit der gefüllten Phiole zu Eridan zurück."}},
[4442]={"Geläutert!",{"Sprecht Eridan gleich noch einmal an."}},
[4449]={"Eingesperrt!",{"Tötet 8 Geologen der Dunkeleisenzwerge und bringt der Person, die im Plumpsklo in der sengenden Schlucht eingesperrt ist, 15 Stücke Seidenstoff."}},
[4450]={"Geschäftsbuch aus Tanaris",{"Nehmt die Abschrift von Goodsteels Geschäftsbuch und beschafft Euch dann die darin aufgeführten Gegenstände, ehe Ihr Krinkle Goodsteel in Tanaris aufsucht."}},
[4451]={"Der Schlüssel zur Freiheit",{"Sucht in der sengenden Schlucht, bis Ihr etwas findet, wofür man den Schlüssel des Grimsilt-Nebengebäudes verwenden kann, den Ihr gefunden habt."}},
[4463]={"Buchband des Nachsinnens",nil},
[4481]={"Buchband der Konstitution",nil},
[4482]={"Buchband der Hartnäckigkeit",nil},
[4483]={"Buchband der Widerstandsfähigkeit",nil},
[4484]={"Buchband der Gier",nil},
[4485]={"Der Foliant des Adels",{"Sprecht mit Duthorian Rall in Stormwind."}},
[4486]={"Der Foliant des Adels",{"Sprecht mit Duthorian Rall in Stormwind."}},
[4487]={"Teufelsross beschwören",{"Sprecht mit Strahad Farsan in Ratchet."}},
[4488]={"Teufelsross beschwören",{"Sprecht mit Strahad Farsan in Ratchet."}},
[4489]={"Teufelsross beschwören",{"Sprecht mit Strahad Farsan in Ratchet."}},
[4490]={"Teufelsross beschwören",{"Sprecht in Ratchet mit Strahad Farsan, um zu lernen, wie man ein Teufelsross beschwört."}},
[4491]={"Etwas Hilfe von guten Freunden",{"Führt Ringo zu Spraggle Frock in Marshals Zuflucht.","","Falls Ringo ohnmächtig werden sollte, verwendet Spraggles Feldflasche, um ihn zu beleben."}},
[4492]={"Verloren!",{"Sucht Ringo am Feuerfedergrat."}},
[4493]={"Der Marsch der Silithiden",{"Sprecht in Gadgetzan mit Alchimist Pestlezugg."}},
[4494]={"Der Marsch der Silithiden",{"Sprecht in Gadgetzan mit Alchimist Pestlezugg."}},
[4495]={"Ein guter Freund",{"Sucht Iverron an der Höhle im Norden."}},
[4496]={"Dschungelei",{"Bringt eine Gorishiduftdrüse und 5 Un'Goro-Erdproben zu Alchimist Pestlezugg in Gadgetzan."}},
[4501]={"Vorsicht, Pterrordax!",{"Tötet 10 Pterrordax und 15 rasende Pterrordax und sprecht dann mit Spraggle Frock in Marshals Zuflucht."}},
[4502]={"Vulkanische Aktivität",{"Sammelt 9 Proben Un'Goro-Asche von den Feuerelementare am Vulkan im Un'Goro Krater ein und bringt die Proben zu Liv Rizzlefix in Ratchet."}},
[4503]={"Shizzles Flieger",{"Sammelt 8 eingesponnene Dimetrodon-Schuppen und 8 eingesponnene Pterrordax-Schuppen für Shizzle in Marshals Zuflucht."}},
[4504]={"Superkleber",{"Sammelt 12 Proben superklebrigen Teer für Tran'rek in Gadgetzan."}},
[4505]={"Brunnen der Verderbnis",{"Beschafft eine Probe verderbten Wassers vom Mondbrunnen der Jadefeuersatyrn und bringt sie zu Winna Hazzard am Blutgiftposten."}},
[4506]={"Verderbte Säbler",{"Bringt Winnas Kätzchen zum verderbten Mondbrunnen, lasst es dort frei und bringt es dann wieder zu Winna zurück.","","Sobald Ihr wieder bei Winna seid, klickt auf die Katze, um sie Winna zu übergeben."}},
[4507]={"Bauer schlägt Dame",{"Besiegt die Schwarmkönigin der Gorishi, sobald sie erscheint.","","Bringt das Gehirn der Schwarmkönigin zu Alchimist Pestlezugg nach Gadgetzan."}},
[4508]={"Die Ruhe vor dem Sturm",{"Bringt Pestlezuggs Un'Goro-Bericht zu Gracina Spiritmight in Darnassus."}},
[4509]={"Die Ruhe vor dem Sturm",{"Bringt Pestlezuggs Un'Goro-Bericht zu Zilzibin Drumlore in Orgrimmar."}},
[4510]={"Die Ruhe vor dem Sturm",{"Bringt den Bankgutschein zu Idriana in der Bank von Darnassus."}},
[4511]={"Die Ruhe vor dem Sturm",{"Bringt den Bankgutschein zu Karus in der Bank von Orgrimmar."}},
[4512]={"Brühschleimer auf Abwegen",{"Bringt 6 mit verfluchten Brühschlammern gefüllte Behälter und 6 mit besudelten Brühschlammern gefüllte Behälter zu Laris Geardawdle in Ironforge."}},
[4513]={"Brühschleimer auf Abwegen",{"Bringt 10 mit reinen Proben gefüllte Krüge zu Laris Geardawdle in Ironforge.","","Falls Ihr Probleme habt, fündig zu werden, dann kann Laris Euch vielleicht noch den einen oder anderen Hinweis geben."}},
[4521]={"Wilde Wächter",{"Trull Failbane im Teufelswald möchte, dass Ihr 15 tobende Eulenbestien und 15 struppige Eulenbestien tötet."}},
[4542]={"Nachricht zum Freiwindposten",{"Bringt Klippenbehüter Longhorn am Freiwindposten die dringende Nachricht."}},
[4561]={"Test auf Unreinheiten - Un'Goro Krater",nil},
[4581]={nil,{"Bringt Shindrells Notiz zu Kayneth Stillwind in Forest Song."}},
[4621]={"Holla, Admiral!",{"Tötet Flottenmeister Seehorn und Baron Revilgaz aus Booty Bay und kehrt dann zu Flottenmeister Firallon zurück. Er befindet sich auf der CRIMSON VEIL vor der Küste des Schlingendorntals."}},
[4641]={"Euer Platz in der Welt",{"Sprecht mit Gornek. Euch fällt ein, dass Kaltunk auf Eurer Karte markiert hat, wo er sich befindet. Außerdem erwähnte er, dass Gornek sich im Höhlenbau aufhielte, einem Gebäude im Westen."}},
[4642]={"Vereinigung von Einflüssen",{"Bringt eine verschmolzene Brühschlammerprobe zum Chemiker Fuely in Undercity."}},
[4661]={"Test für Verderbnis - Teufelswald",nil},
[4681]={"An Land gespült",{"Bergt die Meeresschildkrötenüberreste der skelettierten Meeresschildkröte in den Gewässern westlich von Auberdine und sprecht anschließend in Auberdine mit Gwennyth Bly'Leggonde."}},
[4701]={"Stellt sie ab",{"Begebt Euch zur Blackrockspitze und vernichtet die Quelle der Bedrohung durch die Worgs. Als Ihr Helendis verlasst, ruft er Euch noch einen Namen hinterher: Halycon. Darauf beziehen sich die Orcs im Zusammenhang mit den Worgs."}},
[4721]={"Wilde Wächter",{"Trull Failbane im Teufelswald möchte, dass Ihr in Winterspring 10 Berserkereulenbestien jagt."}},
[4722]={"Gestrandete Meeresschildkröte",{"Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde."}},
[4723]={"Gestrandete Meereskreatur",{"Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."}},
[4724]={"Die Herrin der Meute",{"Erschlagt Halycon, die Rudelführerin der Worgs der Blutäxte."}},
[4725]={"Gestrandete Meeresschildkröte",{"Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde."}},
[4726]={"Brutlingessenz",{"Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe."}},
[4727]={"Gestrandete Meeresschildkröte",{"Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde."}},
[4728]={"Gestrandete Meereskreatur",{"Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."}},
[4729]={"Kiblers Exotische Tiere",{"Begebt Euch zur Blackrockspitze und sucht Worgwelpen der Blutäxte. Benutzt den Käfig, um die wilden kleinen Bestien zu transportieren. Bringt einen eingesperrten Worgwelpen zu Kibler."}},
[4730]={"Gestrandete Meereskreatur",{"Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."}},
[4731]={"Gestrandete Meeresschildkröte",{"Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde."}},
[4732]={"Gestrandete Meeresschildkröte",{"Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde."}},
[4733]={"Gestrandete Meereskreatur",{"Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde."}},
[4734]={"Ei-Frosten",{"Benutzt den Prototyp des Eiszilloskops an einem Ei im Horst."}},
[4735]={"Eiersammlung",{"Bringt 8 eingesammelte Dracheneier sowie das kollektronische Modul zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe."}},
[4736]={"Auf der Suche nach Menara Voidrender",{"Sprecht mit Menara Voidrender im Brachland."}},
[4737]={"Auf der Suche nach Menara Voidrender",{"Sprecht mit Menara Voidrender im Brachland."}},
[4738]={"Auf der Suche nach Menara Voidrender",{"Sprecht im Brachland mit Menara Voidrender."}},
[4739]={"Auf der Suche nach Menara Voidrender",{"Sprecht mit Menara Voidrender im Brachland."}},
[4740]={"GESUCHT: Gurgelbacke!",{"Sucht und tötet den Murloc namens Gurgelbacke. Man nimmt an, dass die Kreatur die Hütten der Murlocs am Strand südlich von Auberdine beschützt.","","Informiert Schildwache Glynda Nal'Shea über Gurgelbackes Tod."}},
[4741]={"Wilde Wächter",{"Trull Failbane im Teufelswald möchte, dass Ihr in Winterspring 13 mondbestrahlte Eulenbestien jagt."}},
[4742]={"Siegel des Aufstiegs",{"Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück.","","Vaelan nannte Euch auch die Namen der drei Generäle: Kriegsmeister Voone von den Gluthauern, Hochlord Omokk von den Felsspitzogern und Oberanführer Wyrmthalak von den Blutäxten."}},
[4743]={"Siegel des Aufstiegs",{"Reist zum Drachensumpf in den Marschen von Dustwallow. Sucht den alten Drachen Aschenschwinge auf und bekämpft ihn ohne Gnade, bis sein Wille gebrochen ist.","","In genau diesem Moment müsst Ihr das ungeschmiedete Siegel des Aufstiegs vor der großen Bestie hinlegen. Dann müsst Ihr schnell die Kugel der drachischen Energie auf seine geschwächte Gestalt anwenden und die Kontrolle über seine geistigen Kräfte übernehmen. Kontrolliert die Bestie und zwingt die Flammen des schwarzen Drachenschwarms auf das ungeschmiedete Siegel des Aufstiegs!"}},
[4761]={"Thundris Windwirker",{"Sprecht mit Thundris Windwirker in Auberdine."}},
[4762]={"Der Cliffspring",{"Geht von Auberdine aus nach Norden zum ersten Wasserfall des Cliffspring und entnehmt aus dem Teich dort eine Probe.","","Kehrt mit der Cliffspringprobe zu Thundris Windwirker nach Auberdine zurück."}},
[4763]={"Die verderbten Schwarzfelle",{"Füllt die leere Säuberungsschale am Mondbrunnen in Auberdine.","","Holt jeweils eine Probe von Früchten, Nüssen und Getreide aus dem Lager der Schwarzfellfurbolgs im Norden.","","Mischt alles in der Schale und stellt diese bei dem Freudenfeuer neben dem Cliffspring auf Höhe des nördlichen Lagers ab und lockt dadurch den Satyrverderber an.","","Nehmt den Talisman der Verderbnis und bringt ihn zu Thundris Windwirker in Auberdine."}},
[4764]={"Doomriggers Schnalle",{"Bringt Mayara Brightwing in der brennenden Steppe Doomriggers Schnalle."}},
[4765]={"Lieferung an Ridgewell",{"Bringt Ridgewells Kiste zu Remington Ridgewell nach Stormwind."}},
[4766]={nil,{"Sprecht mit Mayara Brightwing in der brennenden Steppe."}},
[4767]={"Windreiter",{"Bringt Elu am Freiwindposten 10 Eier von Steilhangflügeldrachen."}},
[4768]={"Die Darkstone-Schrifttafel",{"Bringt der Schattenmagierin Vivian Lagrave in Kargath die Darkstone-Schrifttafel."}},
[4769]={"Vivian Lagrave und die Darkstone-Schrifttafel",{"Sprecht mit Schattenmagierin Vivian Lagrave."}},
[4770]={"Auf der Heimreise",{"Begleitet Pao'ka Swiftmountain aus dem Steilhang heraus und sprecht dann am Weißgipfelposten mit Motega Firemane."}},
[4771]={"Dämmerungstrickfalle",{"Legt die Dämmerungstrickfalle in den Vorführraum von Scholomance. Besiegt Vectus und kehrt dann zu Betina Bigglezink zurück."}},
[4781]={"Komponenten für die verzauberte Goldblutrobe",{"Bringt Xizk Goodstitch im Schlingendorntal einen Goldbarren."}},
[4782]={"Komponenten für die verzauberte Goldblutrobe",{"Kehrt zu Menara Voidrender im Brachland zurück."}},
[4783]={"Komponenten für die verzauberte Goldblutrobe",{"Bringt Menara Voidrender im Brachland 10 Phiolen Zornsäerblut und 1 geringen Höllenstein."}},
[4784]={"Komponenten für die verzauberte Goldblutrobe",{"Bringt Menara Voidrender im Brachland Goldgarn, 2 glimmende Kohlen und einen Seelensplitter."}},
[4785]={"Feiner Goldfaden",nil},
[4786]={"Die fertig gestellte Robe",{"Wartet, bis Menara Voidrender Eure Robe fertig gestellt hat, und sprecht dann noch einmal mit ihr."}},
[4787]={"Das uralte Ei",{"Bringt das uralte Ei zu Yeh'kinya nach Tanaris."}},
[4788]={"Die letzten Schrifttafeln",{"Bringt Ausgrabungsleiter Ironboot in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru."}},
