[5525]={"Befreit Knot!",nil},
[5526]={"Die Splitter der Teufelsranke",{"Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach, werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Requiliar der Reinheit, um darin den Splitter sicher zu versiegeln und bringt das versiegelte Reliquiar zu Rabine Saturna in Nighthaven, Moonglade."}},
[5527]={"Ein Reliquiar der Reinheit",{"Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nighthaven, Moonglade zurück."}},
[5528]={"Der Gordokgeschmackstest",nil},
[5529]={"Verseuchte Jungtiere",{"Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts zurück."}},
[5531]={nil,{"Bringt die gefrorenen Eier zu Betina Bigglezink."}},
[5533]={nil,{"Sprecht mit Alchimist Arbington an der Chillwindspitze, Westliche Pestländer."}},
[5534]={"Kim'jaels 'fehlende' Ausrüstung",{"Sucht, in den Ruinen von Eldarath irgendeine Rune, die die Naga in ihrem Besitz haben, und bringt sie Kim'jal in Azshara."}},
[5535]={"Spirituelle Unruhe",{"Vernichtet 6 Erscheinungen einer Hochgeborenen und 6 Lichlinge eines Hochgeborenen, bevor Ihr zu Loh'atu in Azshara zurückkehrt."}},
[5536]={"Ein Land voller Hass",{"Tötet 6 Satyrn der Haldarr, 2 Schwindler der Haldarr sowie 2 Teufelsanbeter der Haldarr und kehrt dann zu Loh'atu an der Grenze zu Ashenvale zurück."}},
[5537]={"Skelettfragmente",{"Bringt 15 Skelettfragmente zu Alchimist Arbington an der Chillwindspitze, Westliche Pestländer."}},
[5538]={"Sold reimt sich auf...",{"Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goodsteel in Gadgetzan."}},
[5541]={"Munition für Rumbleshot",{"Bringt Rumbleshots Munition zu Hegnar Rumbleshot in Dun Morogh."}},
[5542]={"Dämonenhunde",{"Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt."}},
[5543]={"Blutgefärbter Himmel",{"Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück."}},
[5544]={"Aassammlung",{"Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt."}},
[5545]={"Ein Bündel Probleme",{"Bringt 8 Holzbündel zu Raelen beim Holzfällerlager des Osttals."}},
[5561]={"Kodozusammentrieb",{"Bringt fünf gezähmte Kodos sowie den Kodokombobulator zu Smeed Scrabblescrew bei Scrabblescrews Lager."}},
[5581]={"Portale der Legion",{"Verbannt 6 Portale in Mannorocs Koven und kehrt dann zu Taiga Wisemane nach Shadowprey zurück."}},
[5582]={"Gesunde Großdrachenschuppe",{"Bringt die gesunde Großdrachenschuppe zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern."}},
