[6826]={"Ruf der Lüfte - Jeztors Luftflotte",nil},
[6827]={"Ruf der Lüfte - Mulvericks Luftflotte",nil},
[6844]={"Umber, Archivar",{"Bringt das verkrustete Silithidenobjekt zu Umber, dem Archivar des Zirkels des Cenarius, ins Dorf Nighthaven in Moonglade."}},
[6845]={"Enthüllung von Geheimnissen der Vergangenheit",{"Sprecht mit Rabine Saturna im Dorf Nighthaven in Moonglade."}},
[6846]={"Der Angriff soll beginnen!",nil},
[6881]={"Ivus der Waldfürst",nil},
[6921]={"Inmitten der Ruinen",{"Bringt den Fathom-Kern zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale."}},
[6922]={nil,{"Bringt die seltsame Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale."}},
