MUI_MountDB:Localize(loadstring([=[return {
[22719]={name="Schwarzer Schlachtenschreiter",lore="Ein ordentlich beschleunigter Gnom in der Schlacht ist etwas schrecklich Schönes. - Hochtüftler Mekkadrill"},
[26656]={name="Schwarze Qirajipanzerdrohne",lore="Auch wenn noch immer viele Arten der Qirajipanzerdrohne in den Ruinen von Ahn'Qiraj entdeckt werden können, wurden die dunkelste Spezies nur zu Zeiten des hallenden Skarabäusgongs erblickt."},
[470]={name="Rappe",lore="Wird angeblich wegen seines dunklen Fells von der SI:7 bei Nachtmissionen bevorzugt."},
[22718]={name="Schwarzer Kriegskodo",lore="Die Stallmeister der Kor'kron züchten die schwarzen Kriegskodos wegen ihres aggressiven und unberechenbaren Verhaltens. Ihr Trompeten zeigt an, dass bald Blut fließen wird.",vendor="Räuber Bork"},
[22720]={name="Schwarzer Kriegswidder",lore="Die Zwerge lieben ihre Widdergefährten, weil diese sich furchtlos ins Gefecht stürzen."},
[22721]={name="Schwarzer Kriegsraptor",lore="Aus derselben brutalen Familie der Raptoren gezüchtet, die auch Ohgan gezeugt und dem Imperium der Gurubashi den Sieg gebracht hat.",vendor="Räuber Bork"},
[22717]={name="Schwarzes Schlachtross",lore="Dazu ausgebildet, den heftigsten Nahkampf auf den grausamsten Schlachtfeldern auszuhalten."},
[22723]={name="Schwarzer Kriegstiger",lore="Wie die entfernt verwandten Nachtsäbler sind Tiger für ihre messerscharfen Klauen, ihre unglaubliche Beweglichkeit und ihre Liebe dafür, hinter den Ohren gekrault zu werden, bekannt."},
[22724]={name="Schwarzer Kriegswolf",lore="Werden von den Wachen von Orgrimmar wegen ihres gut ausgeprägten Geruchssinns geschätzt.",vendor="Räuber Bork"},
